from collections.abc import Mapping

from .repository import get_existing_emails, put_contact

_ROW_FIELDS = {"email", "name"}

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_rows(rows):
    """Validate and normalize a complete batch of rows before any write."""
    if rows is None or isinstance(rows, (str, bytes, Mapping)):
        raise ValueError("rows must be an iterable of contact rows")
    try:
        candidates = list(rows)
    except TypeError:
        raise ValueError("rows must be an iterable of contact rows") from None

    validated = []
    seen = set()
    for index, row in enumerate(candidates):
        if not isinstance(row, Mapping):
            raise ValueError("row %d must be an object" % index)
        if set(row.keys()) != _ROW_FIELDS:
            raise ValueError("row %d must contain exactly the email and name fields" % index)

        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("row %d email and name must be strings" % index)

        email = email.strip().lower()
        name = name.strip()

        if email.count("@") != 1:
            raise ValueError("row %d email must contain exactly one @" % index)
        local, _, domain = email.partition("@")
        if not local or not domain:
            raise ValueError("row %d email must have nonempty sides" % index)
        if any(character.isspace() for character in email):
            raise ValueError("row %d email must not contain whitespace" % index)
        if not name:
            raise ValueError("row %d name must not be empty" % index)

        if email in seen:
            raise ValueError("row %d duplicates email %r" % (index, email))
        seen.add(email)
        validated.append((email, name))
    return validated

def import_contacts(connection, rows):
    validated = _validate_rows(rows)
    if not validated:
        return {"inserted": 0, "updated": 0}

    emails = [email for email, _ in validated]
    inserted = 0
    updated = 0
    with connection:
        existing = get_existing_emails(connection, emails)
        for email, name in validated:
            put_contact(connection, email, name)
            if email in existing:
                updated += 1
            else:
                inserted += 1
    return {"inserted": inserted, "updated": updated}
